/**
 * @summary Facebook webhook verification
 */
export const getVerifyFacebookWebhookUrl = (
  params?: VerifyFacebookWebhookParams,
) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/webhook/facebook?${stringifiedParams}`
    : `/api/webhook/facebook`;
};

export const verifyFacebookWebhook = async (
  params?: VerifyFacebookWebhookParams,
  options?: RequestInit,
): Promise<string> => {
  return customFetch<string>(getVerifyFacebookWebhookUrl(params), {
    ...options,
    method: "GET",
  });
};

export const getVerifyFacebookWebhookQueryKey = (
  params?: VerifyFacebookWebhookParams,
) => {
  return [`/api/webhook/facebook`, ...(params ? [params] : [])] as const;
};

export const getVerifyFacebookWebhookQueryOptions = <
  TData = Awaited<ReturnType<typeof verifyFacebookWebhook>>,
  TError = ErrorType<void>,
>(
  params?: VerifyFacebookWebhookParams,
  options?: {
    query?: UseQueryOptions<
      Awaited<ReturnType<typeof verifyFacebookWebhook>>,
      TError,
      TData
    >;
    request?: SecondParameter<typeof customFetch>;
  },
) => {
  const { query: queryOptions, request: requestOptions } = options ?? {};

  const queryKey =
    queryOptions?.queryKey ?? getVerifyFacebookWebhookQueryKey(params);

  const queryFn: QueryFunction<
    Awaited<ReturnType<typeof verifyFacebookWebhook>>
  > = ({ signal }) =>
    verifyFacebookWebhook(params, { signal, ...requestOptions });

  return { queryKey, queryFn, ...queryOptions } as UseQueryOptions<
    Awaited<ReturnType<typeof verifyFacebookWebhook>>,
    TError,
    TData
  > & { queryKey: QueryKey };
};

export type VerifyFacebookWebhookQueryResult = NonNullable<
  Awaited<ReturnType<typeof verifyFacebookWebhook>>
>;
export type VerifyFacebookWebhookQueryError = ErrorType<void>;

/**
 * @summary Facebook webhook verification
 */

export function useVerifyFacebookWebhook<
  TData = Awaited<ReturnType<typeof verifyFacebookWebhook>>,
  TError = ErrorType<void>,
>(
  params?: VerifyFacebookWebhookParams,
  options?: {
    query?: UseQueryOptions<
      Awaited<ReturnType<typeof verifyFacebookWebhook>>,
      TError,
      TData
    >;
    request?: SecondParameter<typeof customFetch>;
  },
): UseQueryResult<TData, TError> & { queryKey: QueryKey } {
  const queryOptions = getVerifyFacebookWebhookQueryOptions(params, options);

  const query = useQuery(queryOptions) as UseQueryResult<TData, TError> & {
    queryKey: QueryKey;
  };

  return { ...query, queryKey: queryOptions.queryKey };
}

